
(function(){
 const URL='https://vdxkknftyssjyfbdieqa.supabase.co/rest/v1/rpc/lift_cartera_admin',KEY='sb_publishable_ECuhXuKIb85kj9fgdEjrAw_O7uNpZsh',PASS='liftAdminCloudPasswordV1';
 let rows=[];const $=id=>document.getElementById(id),money=n=>typeof fmt==='function'?fmt(Number(n||0)):'$'+Number(n||0).toLocaleString('es-CO');
 const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
 const password=()=>{try{return sessionStorage.getItem(PASS)||''}catch(e){return ''}};
 async function rpc(action,payload={}){const r=await fetch(URL,{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({p_password:password(),p_action:action,p_payload:payload})});const j=await r.json().catch(()=>null);if(!r.ok)throw new Error(j?.message||j?.error||'No se pudo consultar cartera');return j}
 function installButton(){const row=document.querySelector('.liftAdminToolsRow');if(!row||$('liftCarteraOpenBtn'))return;const b=document.createElement('button');b.id='liftCarteraOpenBtn';b.className='liftCarteraBtn';b.type='button';b.innerHTML='💳 Cartera';b.onclick=liftOpenCartera;row.appendChild(b)}
 function itemLines(x){const a=Array.isArray(x.items)?x.items:[];return a.map(i=>`${Number(i.cantidad||1)} ${i.nombre||'Producto'}${i.marca?' · '+i.marca:''} — ${money(i.total_linea||Number(i.precio_unitario||0)*Number(i.cantidad||1))}`)}
 function debtText(x){const lines=[`Pedido #${x.pedido_id} · ${x.fecha_deuda||''}`,...itemLines(x),`Total: ${money(x.total)}`,`Abonado: ${money(x.abonado)}`,`Saldo pendiente: ${money(x.saldo)}`];if(x.fecha_vencimiento)lines.push(`Vencimiento: ${x.fecha_vencimiento}`);return lines.join('\n')}
 async function copyText(t){try{await navigator.clipboard.writeText(t);alert('Información copiada para WhatsApp.')}catch(e){const a=document.createElement('textarea');a.value=t;document.body.appendChild(a);a.select();document.execCommand('copy');a.remove();alert('Información copiada para WhatsApp.')}}
 window.liftOpenCartera=async function(){$('liftCarteraModal')?.classList.add('open');await liftLoadCartera()};window.liftCloseCartera=function(){$('liftCarteraModal')?.classList.remove('open')};
 window.liftLoadCartera=async function(){try{const j=await rpc('list');rows=Array.isArray(j)?j:[];liftRenderCartera()}catch(e){$('liftCarteraList').innerHTML='<div class="liftCarteraEmpty">'+esc(e.message)+'</div>'}};
 window.liftRenderCartera=function(){
  const q=($('liftCarteraSearch')?.value||'').toLowerCase().trim(),today=new Date().toISOString().slice(0,10);let active=rows.filter(x=>Number(x.saldo)>0);
  $('liftStatTotal').textContent=money(active.reduce((s,x)=>s+Number(x.saldo||0),0));$('liftStatVencida').textContent=money(active.filter(x=>x.fecha_vencimiento&&x.fecha_vencimiento<today).reduce((s,x)=>s+Number(x.saldo||0),0));$('liftStatClientes').textContent=String(new Set(active.map(x=>x.cliente_id)).size);
  if(q)active=active.filter(x=>(String(x.nombre||'')+' '+String(x.celular||'')).toLowerCase().includes(q));const box=$('liftCarteraList');if(!active.length){box.innerHTML='<div class="liftCarteraEmpty">No hay saldos pendientes.</div>';return}
  const groups=new Map();active.forEach(x=>{const k=String(x.cliente_id);if(!groups.has(k))groups.set(k,{cliente_id:x.cliente_id,nombre:x.nombre,celular:x.celular,deudas:[]});groups.get(k).deudas.push(x)});
  box.innerHTML=[...groups.values()].sort((a,b)=>String(a.nombre||'').localeCompare(String(b.nombre||''),'es',{sensitivity:'base'})).map(g=>{const total=g.deudas.reduce((s,x)=>s+Number(x.saldo||0),0),abonado=g.deudas.reduce((s,x)=>s+Number(x.abonado||0),0);return `<section class="liftClientDebt"><div class="liftClientHead"><div><div class="liftClientName">${esc(g.nombre)}</div><div class="liftClientPhone">${esc(g.celular)}</div></div><div class="liftClientTotal"><small>Total pendiente</small><b>${money(total)}</b><small>Abonado ${money(abonado)}</small></div></div><div class="liftClientActions"><button onclick="liftCopyClient(${g.cliente_id})">Copiar todo para WhatsApp</button></div>${g.deudas.map(x=>{const overdue=x.fecha_vencimiento&&x.fecha_vencimiento<today,hist=Array.isArray(x.abonos)?x.abonos:[],items=Array.isArray(x.items)?x.items:[];return `<article class="liftDebt"><div class="liftDebtTop"><div><div class="liftDebtName">Pedido #${x.pedido_id}</div><div class="liftDebtMeta">${esc(x.fecha_deuda||'')}${x.fecha_vencimiento?' · Vence '+esc(x.fecha_vencimiento):''}</div><span class="liftStatus">${overdue?'Vencido':esc(x.estado)}</span></div><div class="liftDebtSaldo"><small>Debe</small><b>${money(x.saldo)}</b><small>de ${money(x.total)}</small></div></div>${items.length?`<div class="liftDebtItems">${items.map(i=>`<div class="liftDebtItem"><span>${esc(i.cantidad||1)} × ${esc(i.nombre||'Producto')}</span><b>${money(i.total_linea||0)}</b></div>`).join('')}</div>`:''}<div class="liftDebtActions"><button onclick="liftToggleAbono(${x.id})">Registrar abono</button><button onclick="liftToggleHistory(${x.id})">Historial (${hist.length})</button><button onclick="liftCopyDebt(${x.id})">Copiar pedido</button></div><div id="liftAbono-${x.id}" class="liftAbonoBox"><input id="liftAbonoValor-${x.id}" type="number" min="1" max="${Number(x.saldo)}" step="1000" placeholder="Valor del abono"><input id="liftAbonoFecha-${x.id}" type="date" value="${today}"><input id="liftAbonoMedio-${x.id}" class="full" placeholder="Medio de pago (Bre-B, Bancolombia, efectivo...)"><input id="liftAbonoNota-${x.id}" class="full" placeholder="Nota opcional"><button class="full" onclick="liftSaveAbono(${x.id})">Guardar abono</button></div><div id="liftHist-${x.id}" class="liftDebtHistory">${hist.length?hist.map(a=>`<div class="liftPayRow"><span>${esc(a.fecha)} · ${esc(a.medio||'Abono')}</span><b>${money(a.valor)}</b></div>`).join(''):'Sin abonos registrados'}</div></article>`}).join('')}</section>`}).join('')
 };
 window.liftCopyDebt=id=>{const x=rows.find(r=>Number(r.id)===Number(id));if(x)copyText(`Hola ${x.nombre||''}.\n\nTe comparto el estado de tu pedido:\n\n${debtText(x)}`)};
 window.liftCopyClient=clienteId=>{const ds=rows.filter(x=>Number(x.cliente_id)===Number(clienteId)&&Number(x.saldo)>0);if(!ds.length)return;const total=ds.reduce((s,x)=>s+Number(x.saldo||0),0);copyText(`Hola ${ds[0].nombre||''}.\n\nTe comparto el estado de tus pedidos:\n\n${ds.map(debtText).join('\n\n')}\n\nTOTAL PENDIENTE: ${money(total)}`)};
 window.liftToggleAbono=id=>$('liftAbono-'+id)?.classList.toggle('open');window.liftToggleHistory=id=>$('liftHist-'+id)?.classList.toggle('open');
 window.liftSaveAbono=async function(id){const valor=Number($('liftAbonoValor-'+id)?.value||0);if(valor<=0){alert('Escribe el valor del abono.');return}try{await rpc('abono',{cartera_id:id,valor,fecha:$('liftAbonoFecha-'+id)?.value||'',medio:$('liftAbonoMedio-'+id)?.value||'',nota:$('liftAbonoNota-'+id)?.value||''});await liftLoadCartera();alert('Abono guardado.')}catch(e){alert(e.message)}};
 const obs=new MutationObserver(installButton);obs.observe(document.body,{childList:true,subtree:true});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(installButton,100));else setTimeout(installButton,100);
})();
